sh "$HOME/skills/tldraw-offline/tq" POST /api/doc/tldr:file:REDACTED/exec '{"code":"const shapes = editor.getCurrentPageShapes();
const byId = Object.fromEntries(shapes.map(s => [s.id, s]));
const cards = shapes.filter(s => s.type === "geo");
const report = cards.map(c => {
  const texts = shapes.filter(s => s.type === "text" && s.x >= c.x && s.x < c.x + c.props.w && s.y >= c.y && s.y < c.y + c.props.h);
  const bottoms = texts.map(t => { const b = editor.getShapePageBounds(t.id); return b ? b.maxY : 0; });
  const maxBottom = bottoms.length ? Math.max(...bottoms) : 0;
  return { card: c.id.split("-")[1] || c.id, cardBottom: c.y + c.props.h, textBottom: Math.round(maxBottom), overflow: Math.round(maxBottom - (c.y + c.props.h)) };
});
const bindings = editor.getCurrentPageBindings();
return { report, arrowBindings: bindings.length }"}'

